rules.logic:
// --- Idempotent guard ---
if (document.getElementById('lang-filter-bar')) return;

// --- Collect all language tags already on the page ---
function getLanguagesFromPage() {
  const langs = new Set();
  document.querySelectorAll('a.tw-tag[aria-label]').forEach(tag => {
    const label = tag.getAttribute('aria-label') || '';
    const match = label.match(/^Tag,\s*(.+)$/);
    if (match) {
      const candidate = match[1].trim();
      // Heuristic: treat as a language tag only if it looks like a real language word
      // (starts with uppercase, no spaces or minimal spaces, not too long)
      if (/^[A-ZÀ-Ö][a-zA-ZÀ-öø-ÿ\u00C0-\u024F\u4E00-\u9FFF]{1,24}$/.test(candidate) && candidate.length <= 25) {
        langs.add(candidate);
      }
    }
  });
  return Array.from(langs).sort();
}

// --- Build the bar ---
const bar = document.createElement('div');
bar.id = 'lang-filter-bar';
bar.style.cssText = [
  'display:flex',
  'align-items:center',
  'flex-wrap:wrap',
  'gap:8px',
  'padding:10px 16px',
  'margin:12px 0 4px 0',
  'background:linear-gradient(135deg,#1f1f23 0%,#18181b 100%)',
  'border:2px solid #9147ff',
  'border-radius:10px',
  'box-shadow:0 2px 14px rgba(145,71,255,.35)',
  'font-family:inherit',
  'z-index:100',
  'position:relative',
].join(';');

// Label
const lbl = document.createElement('span');
lbl.textContent = '🌐 Language Filter:';
lbl.style.cssText = 'color:#efeff1;font-weight:700;font-size:13px;white-space:nowrap;flex-shrink:0;';
bar.appendChild(lbl);

// Select dropdown
const sel = document.createElement('select');
sel.id = 'lang-filter-select';
sel.style.cssText = [
  'background:#0e0e10',
  'color:#efeff1',
  'border:1.5px solid #9147ff',
  'border-radius:6px',
  'padding:5px 10px',
  'font-size:13px',
  'font-weight:600',
  'cursor:pointer',
  'outline:none',
  'min-width:160px',
  'flex-shrink:0',
].join(';');

const allOpt = document.createElement('option');
allOpt.value = 'ALL';
allOpt.textContent = 'Show All Languages';
sel.appendChild(allOpt);

getLanguagesFromPage().forEach(lang => {
  const opt = document.createElement('option');
  opt.value = lang;
  opt.textContent = lang;
  sel.appendChild(opt);
});

// Restore saved preference
const saved = typeof localStorage !== 'undefined' && localStorage.getItem('twitch-lang-filter');
if (saved) sel.value = saved;

bar.appendChild(sel);

// Status badge
const badge = document.createElement('span');
badge.id = 'lang-filter-badge';
badge.style.cssText = [
  'background:#9147ff',
  'color:#fff',
  'border-radius:999px',
  'padding:3px 10px',
  'font-size:11px',
  'font-weight:700',
  'white-space:nowrap',
  'display:none',
].join(';');
bar.appendChild(badge);

// Help text
const help = document.createElement('span');
help.textContent = 'Streams without the selected language tag are hidden.';
help.style.cssText = 'color:#adadb8;font-size:11px;flex:1;min-width:0;';
bar.appendChild(help);

// --- Filter logic ---
function applyFilter() {
  const lang = sel.value;
  if (typeof localStorage !== 'undefined') localStorage.setItem('twitch-lang-filter', lang);
  let hidden = 0, shown = 0;
  document.querySelectorAll('article.ghbJdj').forEach(card => {
    if (lang === 'ALL') {
      card.style.display = '';
      shown++;
    } else {
      const tags = Array.from(card.querySelectorAll('a.tw-tag[aria-label]'));
      const hasLang = tags.some(t => {
        const m = (t.getAttribute('aria-label') || '').match(/^Tag,\s*(.+)$/);
        return m && m[1].trim() === lang;
      });
      if (hasLang) {
        card.style.display = '';
        shown++;
      } else {
        card.style.display = 'none';
        hidden++;
      }
    }
  });
  if (lang !== 'ALL' && hidden > 0) {
    badge.textContent = `${hidden} hidden · ${shown} shown`;
    badge.style.display = '';
  } else {
    badge.style.display = 'none';
  }
}

sel.addEventListener('change', applyFilter);
applyFilter();

// Insert the bar above the tower
element.parentNode.insertBefore(bar, element.nextSibling);

const sel = document.getElementById('lang-filter-select');
if (!sel) return;
const lang = sel.value;
if (lang === 'ALL') {
  element.style.display = '';
  return;
}

// Get tags on this card
const tags = Array.from(element.querySelectorAll('a.tw-tag[aria-label]'));
if (tags.length === 0) return; // tags not yet loaded — do nothing, rule will re-run

const hasLang = tags.some(t => {
  const m = (t.getAttribute('aria-label') || '').match(/^Tag,\s*(.+)$/);
  return m && m[1].trim() === lang;
});

element.style.display = hasLang ? '' : 'none';

// Also refresh the status badge count
const badge = document.getElementById('lang-filter-badge');
if (!badge) return;
const cards = Array.from(document.querySelectorAll('article.ghbJdj'));
const hiddenCount = cards.filter(c => c.style.display === 'none').length;
const shownCount = cards.length - hiddenCount;
if (hiddenCount > 0) {
  badge.textContent = `${hiddenCount} hidden · ${shownCount} shown`;
  badge.style.display = '';
} else {
  badge.style.display = 'none';
}
